"use client";

import React, { useState } from "react";
import { Logo, Sparkline, BarChart, Donut, Stat, Avatar, Toggle } from "./primitives";
import { Icon } from "./icons";

type Pane = "overview" | "attacks" | "models" | "billing" | "integrations";

// ── Sidebar ────────────────────────────────────────────────────
function DashSidebar({ active, setActive }: { active: Pane; setActive: (p: Pane) => void }) {
  const items: { id: Pane; label: string; icon: React.FC<{ size?: number }> }[] = [
    { id: "overview", label: "Обзор", icon: Icon.layers },
    { id: "attacks", label: "Атаки", icon: Icon.warn },
    { id: "models", label: "Модели", icon: Icon.cpu },
    { id: "billing", label: "Баланс", icon: Icon.spark },
    { id: "integrations", label: "Интеграция", icon: Icon.shield },
  ];

  return (
    <div
      style={{
        width: 220,
        borderRight: "1px solid var(--line)",
        background: "var(--surface)",
        display: "flex",
        flexDirection: "column",
        padding: "20px 12px",
        gap: 4,
        flexShrink: 0,
      }}
    >
      <div style={{ padding: "6px 8px 14px" }}>
        <Logo size={13} />
      </div>
      {items.map((item) => {
        const I = item.icon;
        const isActive = active === item.id;
        return (
          <button
            key={item.id}
            onClick={() => setActive(item.id)}
            style={{
              appearance: "none",
              border: 0,
              cursor: "pointer",
              display: "flex",
              alignItems: "center",
              gap: 10,
              padding: "8px 10px",
              borderRadius: 7,
              background: isActive ? "var(--bg-2)" : "transparent",
              color: isActive ? "var(--ink)" : "var(--muted)",
              fontSize: 13,
              fontWeight: isActive ? 500 : 400,
              fontFamily: "var(--font-sans)",
              transition: "background 0.1s",
              textAlign: "left",
            }}
          >
            <I size={15} />
            <span>{item.label}</span>
          </button>
        );
      })}
      <div style={{ flex: 1 }} />
      <div style={{ padding: 12, background: "var(--bg-2)", borderRadius: 8, fontSize: 11.5 }}>
        <div style={{ color: "var(--muted)", marginBottom: 4 }}>Баланс</div>
        <div className="mono" style={{ fontSize: 16, fontWeight: 500, color: "var(--ink)" }}>
          ₽ 184,200
        </div>
        <div style={{ marginTop: 6, color: "var(--muted-2)", fontSize: 10.5 }}>≈ 14 дней работы</div>
      </div>
    </div>
  );
}

// ── Topbar ─────────────────────────────────────────────────────
function DashTopbar({ title, subtitle }: { title: string; subtitle?: string }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        padding: "18px 28px",
        borderBottom: "1px solid var(--line)",
        background: "var(--surface)",
        flexShrink: 0,
      }}
    >
      <div>
        <h1 style={{ margin: 0, fontSize: 20, fontWeight: 600, letterSpacing: "-0.02em" }}>{title}</h1>
        {subtitle && <div style={{ fontSize: 12, color: "var(--muted)", marginTop: 2 }}>{subtitle}</div>}
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        <button className="btn btn-ghost" style={{ padding: "7px 12px", fontSize: 12.5 }}>
          <Icon.refresh size={13} /> Последние 7 дней
        </button>
        <Avatar name="AC" hue={245} />
      </div>
    </div>
  );
}

