// ── Pane: Models ────────────────────────────────────────────────
type Model = {
  id: string;
  name: string;
  kind: string;
  accuracy: number;
  latency: number;
  price: number;
  recommended?: boolean;
};

const MODELS: Model[] = [
  { id: "efn-b7", name: "EfficientNet-B7", kind: "Spatial CNN", accuracy: 96.4, latency: 1.2, price: 0.12, recommended: true },
  { id: "vit-l", name: "Vision Transformer L", kind: "Spatio-temporal", accuracy: 98.9, latency: 2.1, price: 0.34, recommended: true },
  { id: "xception", name: "Xception", kind: "Spatial CNN", accuracy: 94.2, latency: 0.8, price: 0.08 },
  { id: "liveness-cnn", name: "Liveness CNN", kind: "Anti-spoof", accuracy: 99.1, latency: 0.6, price: 0.06, recommended: true },
  { id: "lipsync-tcn", name: "LipSync TCN", kind: "Temporal", accuracy: 92.8, latency: 1.5, price: 0.18 },
  { id: "cpu-fast", name: "CPU-Fast", kind: "Edge inference", accuracy: 88.6, latency: 0.3, price: 0.02 },
];

const DEFAULT_ENABLED: Record<string, boolean> = {
  "efn-b7": true,
  "vit-l": true,
  "xception": false,
  "liveness-cnn": true,
  "lipsync-tcn": false,
  "cpu-fast": false,
};

type ExtraSetting = { label: string; desc: string; on: boolean };
const EXTRA_SETTINGS: ExtraSetting[] = [
  { label: "CPU-проверка перед GPU", desc: "Отсеивает заведомо чистые видео на дешёвой модели", on: true },
  { label: "Параллельный запуск моделей", desc: "Уменьшает задержку, удваивает стоимость GPU", on: false },
  { label: "Сохранять видео для аудита", desc: "Хранение 30 дней. +₽0.04/проверка", on: false },
  { label: "Webhook на каждый результат", desc: "POST на ваш endpoint", on: true },
];

function PaneModels() {
  const [enabled, setEnabled] = useState<Record<string, boolean>>(DEFAULT_ENABLED);
  const [extras, setExtras] = useState(EXTRA_SETTINGS.map((s) => s.on));

  const enabledList = MODELS.filter((m) => enabled[m.id]);
  const totalPrice = enabledList.reduce((s, m) => s + m.price, 0);
  const avgAcc = enabledList.length ? enabledList.reduce((s, m) => s + m.accuracy, 0) / enabledList.length : 0;
  const totalLat = enabledList.reduce((s, m) => s + m.latency, 0);

  return (
    <div style={{ padding: 28, display: "flex", flexDirection: "column", gap: 20 }}>
      {/* Summary */}
      <div className="card" style={{ padding: 20, display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 24 }}>
        <Stat label="МОДЕЛЕЙ ВКЛЮЧЕНО" value={`${enabledList.length} / ${MODELS.length}`} />
        <Stat label="СТОИМОСТЬ ЗА ПРОВЕРКУ" value={`₽ ${totalPrice.toFixed(2)}`} />
        <Stat label="АНСАМБЛЬНАЯ ТОЧНОСТЬ" value={`${avgAcc.toFixed(1)}%`} sub="среднее по моделям" trend="up" />
        <Stat label="ОЖИДАЕМАЯ ЗАДЕРЖКА" value={`${totalLat.toFixed(1)}s`} sub="последовательно" />
      </div>

      {/* Catalog */}
      <div className="card" style={{ padding: 0, overflow: "hidden" }}>
        <div style={{ padding: "16px 20px", borderBottom: "1px solid var(--line)" }}>
          <div style={{ fontSize: 13, fontWeight: 500 }}>Каталог моделей</div>
          <div style={{ fontSize: 11.5, color: "var(--muted)", marginTop: 2 }}>
            Выберите модели для ансамбля. Цена и задержка суммируются.
          </div>
        </div>
        {MODELS.map((m, idx) => {
          const on = enabled[m.id];
          return (
            <div
              key={m.id}
              style={{
                padding: "16px 20px",
                display: "grid",
                gridTemplateColumns: "36px 1.6fr 1fr 1fr 1fr 80px",
                gap: 16,
                alignItems: "center",
                borderBottom: idx < MODELS.length - 1 ? "1px solid var(--line)" : "none",
                background: on ? "var(--surface)" : "var(--bg)",
                opacity: on ? 1 : 0.65,
              }}
            >
              <div
                style={{
                  width: 32,
                  height: 32,
                  borderRadius: 6,
                  background: on ? "var(--accent-soft)" : "var(--bg-2)",
                  color: on ? "var(--accent-ink)" : "var(--muted-2)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                }}
              >
                <Icon.cpu size={16} />
              </div>
              <div>
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  <span style={{ fontSize: 13, fontWeight: 500 }}>{m.name}</span>
                  {m.recommended && (
                    <span
                      style={{
                        fontSize: 10,
                        padding: "1px 6px",
                        borderRadius: 3,
                        background: "var(--accent-soft)",
                        color: "var(--accent-ink)",
                        fontFamily: "var(--font-mono)",
                        letterSpacing: "0.04em",
                        textTransform: "uppercase",
                      }}
                    >
                      rec
                    </span>
                  )}
                </div>
                <div style={{ fontSize: 11.5, color: "var(--muted)", marginTop: 2 }}>{m.kind}</div>
              </div>
              {(
                [
                  ["Точность", `${m.accuracy}%`],
                  ["Задержка", `${m.latency}s`],
                  ["Цена", `₽ ${m.price.toFixed(2)}`],
                ] as [string, string][]
              ).map(([label, val]) => (
                <div key={label}>
                  <div
                    style={{
                      fontSize: 10.5,
                      color: "var(--muted)",
                      textTransform: "uppercase",
                      letterSpacing: "0.04em",
                      fontFamily: "var(--font-mono)",
                    }}
                  >
                    {label}
                  </div>
                  <div className="mono" style={{ fontSize: 13, fontWeight: 500 }}>
                    {val}
                  </div>
                </div>
              ))}
              <div style={{ display: "flex", justifyContent: "flex-end" }}>
                <Toggle value={on} onChange={(v) => setEnabled((e) => ({ ...e, [m.id]: v }))} />
              </div>
            </div>
          );
        })}
      </div>

      {/* Extra settings */}
      <div className="card" style={{ padding: 20 }}>
        <div style={{ fontSize: 13, fontWeight: 500, marginBottom: 4 }}>Доп. настройки</div>
        <div style={{ fontSize: 11.5, color: "var(--muted)", marginBottom: 16 }}>Влияют на стоимость и точность.</div>
        <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
          {EXTRA_SETTINGS.map((setting, i) => (
            <div
              key={i}
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                padding: "10px 0",
                borderBottom: i < EXTRA_SETTINGS.length - 1 ? "1px solid var(--line)" : "none",
              }}
            >
              <div>
                <div style={{ fontSize: 13, fontWeight: 500 }}>{setting.label}</div>
                <div style={{ fontSize: 11.5, color: "var(--muted)" }}>{setting.desc}</div>
              </div>
              <Toggle
                value={extras[i]}
                onChange={(v) =>
                  setExtras((prev) => {
                    const next = [...prev];
                    next[i] = v;
                    return next;
                  })
                }
              />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

