const PANE_META: Record<Pane, { title: string; subtitle: string }> = {
  overview: { title: "Обзор", subtitle: "Сводка по проверкам за неделю" },
  attacks: { title: "Атаки", subtitle: "Детальная аналитика по векторам" },
  models: { title: "Модели", subtitle: "Конфигурация ансамбля и тарифов" },
  billing: { title: "Баланс", subtitle: "Пополнение и история списаний" },
  integrations: { title: "Интеграция", subtitle: "API ключи, webhook, redirect URL" },
};

export function Dashboard({ initialPane = "overview" }: { initialPane?: Pane }) {
  const [active, setActive] = useState<Pane>(initialPane);
  const meta = PANE_META[active];

  return (
    <div style={{ display: "flex", height: "100%", background: "var(--bg)", overflow: "hidden" }}>
      <DashSidebar active={active} setActive={setActive} />
      <div style={{ flex: 1, display: "flex", flexDirection: "column", minWidth: 0, overflow: "hidden" }}>
        <DashTopbar title={meta.title} subtitle={meta.subtitle} />
        <div style={{ flex: 1, overflow: "auto", minHeight: 0 }}>
          {active === "overview" && <PaneOverview />}
          {active === "attacks" && <PaneAttacks />}
          {active === "models" && <PaneModels />}
          {active === "billing" && <PaneBilling />}
          {active === "integrations" && <PaneIntegrations />}
        </div>
      </div>
    </div>
  );
}
